// The exact module paths can differ across burn versions; use a minimal probe by relying on TensorData only.
// We'll avoid backend execution: TensorData conversion should work directly.

// The probe environment expects we can use unwind-safe panic capture.

fn store_conversions_i32() -> (Vec<(String, Result<Vec<u8>, String>)>, Vec<(String, Result<Vec<u8>, String>)>) {
    let stores = vec![
        ("U8".to_string(), burn::tensor::BoolStore::U8),
        ("U32".to_string(), burn::tensor::BoolStore::U32),
        ("Native".to_string(), burn::tensor::BoolStore::Native),
    ];

    let td = TensorData::from([-1i32, 0, 1, -12]);

    let mut records: Vec<(String, Result<Vec<u8>, String>)> = Vec::new();
    for (name, store) in stores {
        let res = std::panic::catch_unwind(|| {
            let td_bool = td.convert_dtype(DType::Bool(store));
            // Convert TensorData<bool> into Vec<u8> for stable capture.
            // Many TensorData bool types store as u8; use into_vec.
            let v: Vec<bool> = td_bool.into_data().to_vec();
            v.into_iter().map(|b| if b {1u8} else {0u8}).collect::<Vec<u8>>()
        });
        match res {
            Ok(v) => records.push((name, Ok(v))),
            Err(_) => records.push((name, Err("panic".to_string()))),
        }
    }
    (records, Vec::new())
}

